-- স্কিমা-যাচাই: প্রোডাকশন ডেটাবেস ০০০১–০০০৭ মাইগ্রেশনের ফল কি না।
-- Supabase → SQL Editor-এ পুরোটা চালান। ফলাফলে কোনো সারি "নেই" বা "বাড়তি" দেখালে সেটি মেলেনি।
-- (এই ফাইল স্বয়ংক্রিয়ভাবে তৈরি: node supabase/tools/gen_verify.mjs)
with want as (
  select 'ফাংশন' kind, unnest(array['accept_access_link','ack_recovery','add_adjustment','add_payment','add_purchase','cancel_access_link','cancel_payment','confirm_payment','create_group','create_member_invitation','delete_group','delete_my_account','delete_purchase','end_pause','finalize_month','group_months','group_name_by_code','issue_access_link','join_group','leave_group','list_corrections','month_report','pending_access_links','preview_access_link','preview_split','reject_payment','remind_payment','remove_member','remove_push_subscription','request_correction','resolve_correction','save_push_subscription','send_test_push','set_pause','set_push','transfer_admin','update_purchase']) name
  union all select 'টেবিল', unnest(array['access_links','corrections','events','groups','member_invitations','members','months','pauses','payments','profiles','purchase_history','purchase_items','purchase_shares','purchases','push_subscriptions'])
  union all select 'কলাম', unnest(array['private.access_links.created_at','private.access_links.group_id','private.access_links.label','private.access_links.purpose','private.access_links.target','private.access_links.token','private.member_invitations.code','private.member_invitations.created_at','private.member_invitations.email','private.member_invitations.group_id','private.member_invitations.redeemed','public.corrections.amount','public.corrections.bazar_date','public.corrections.buyer_id','public.corrections.client_token','public.corrections.created_at','public.corrections.description','public.corrections.group_id','public.corrections.id','public.corrections.items','public.corrections.kind','public.corrections.month','public.corrections.purchase_id','public.corrections.reason','public.corrections.requested_by','public.corrections.resolve_note','public.corrections.resolved_at','public.corrections.resolved_by','public.corrections.status','public.events.actor_id','public.events.created_at','public.events.group_id','public.events.id','public.events.kind','public.events.message','public.groups.created_at','public.groups.currency_code','public.groups.currency_decimals','public.groups.currency_gen','public.groups.currency_name','public.groups.currency_symbol','public.groups.id','public.groups.invite_code','public.groups.name','public.members.created_at','public.members.display_name','public.members.group_id','public.members.id','public.members.joined_on','public.members.left_on','public.members.recovery_saved_at','public.members.role','public.members.seq','public.members.user_id','public.months.finalized_at','public.months.finalized_by','public.months.group_id','public.months.month','public.months.report','public.pauses.created_at','public.pauses.end_date','public.pauses.group_id','public.pauses.id','public.pauses.member_id','public.pauses.start_date','public.payments.amount','public.payments.client_token','public.payments.created_at','public.payments.from_id','public.payments.group_id','public.payments.id','public.payments.kind','public.payments.month','public.payments.note','public.payments.reminded_at','public.payments.resolved_at','public.payments.status','public.payments.to_id','public.profiles.created_at','public.profiles.id','public.profiles.name','public.profiles.push_enabled','public.purchase_history.action','public.purchase_history.changed_at','public.purchase_history.changed_by','public.purchase_history.group_id','public.purchase_history.id','public.purchase_history.purchase_id','public.purchase_history.snapshot','public.purchase_items.amount','public.purchase_items.group_id','public.purchase_items.id','public.purchase_items.name','public.purchase_items.purchase_id','public.purchase_shares.group_id','public.purchase_shares.member_id','public.purchase_shares.purchase_id','public.purchase_shares.share','public.purchases.amount','public.purchases.bazar_date','public.purchases.buyer_id','public.purchases.client_token','public.purchases.created_at','public.purchases.created_by','public.purchases.deleted_at','public.purchases.description','public.purchases.group_id','public.purchases.id','public.purchases.month','public.purchases.updated_at','public.push_subscriptions.auth','public.push_subscriptions.created_at','public.push_subscriptions.endpoint','public.push_subscriptions.id','public.push_subscriptions.p256dh','public.push_subscriptions.user_id'])
  union all select 'পলিসি', unnest(array['corrections.corrections_read','events.events_read','groups.groups_read','members.members_read','months.months_read','pauses.pauses_read','payments.payments_read','profiles.profiles_self','purchase_history.history_read','purchase_items.items_read','purchase_shares.shares_read','purchases.purchases_read'])
), have as (
  select 'ফাংশন' kind, p.proname name from pg_proc p join pg_namespace s on s.oid=p.pronamespace where s.nspname='public'
  union all select 'টেবিল', table_name from information_schema.tables where table_schema in ('public','private') and table_type='BASE TABLE'
  union all select 'কলাম', table_schema||'.'||table_name||'.'||column_name from information_schema.columns where table_schema in ('public','private')
  union all select 'পলিসি', tablename||'.'||policyname from pg_policies where schemaname='public'
)
select 'নেই' status, w.kind, w.name from want w left join have h using (kind, name) where h.name is null and w.kind <> 'টেবিল'
union all
select 'নেই', w.kind, w.name from want w left join have h using (kind, name) where h.name is null and w.kind = 'টেবিল' and w.name not in ('users')
union all
select 'বাড়তি (public ফাংশন/পলিসি)', h.kind, h.name from have h left join want w using (kind, name) where w.name is null and h.kind in ('ফাংশন','পলিসি')
order by 1, 2, 3;
-- ফাঁকা ফল = স্কিমা মিলেছে।

-- নিরাপত্তা-যাচাই (প্রতিটির ফল ফাঁকা হতে হবে)
-- ১) anon শুধু দুটি ফাংশন চালাতে পারবে:
select p.proname as "anon-এর বাড়তি অনুমতি" from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public' and has_function_privilege('anon', p.oid, 'execute') and p.proname not in ('group_name_by_code','preview_access_link');
-- ২) private টেবিল কেউ সরাসরি পড়তে পারবে না:
select c.relname as "পড়া যায় এমন private টেবিল" from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname='private' and c.relkind='r' and (has_table_privilege('authenticated', c.oid, 'select') or has_table_privilege('anon', c.oid, 'select'));
-- ৩) RLS বন্ধ এমন public টেবিল:
select c.relname as "RLS বন্ধ" from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname='public' and c.relkind='r' and not c.relrowsecurity;
